{
  "name": "轮询式内部伪设备",
  "name_en": "Polled Internal Pseudo-Device",
  "manufacturer": "",
  "description": "这是一个非物理的软件组件，用于以后台轮询方式监测操作系统或主机内部状态，并将结果表现为可触发激活/失活事件的“伪设备”。它适合在实验自动化中把网络连通性、CPU 温度、系统负载、时间窗口或磁盘占用等内部条件，作为控制其他真实实验设备或流程逻辑的触发信号。",
  "description_en": "This is a non-physical software component that polls operating-system or host-internal state in the background and exposes it as a pseudo-device with active/inactive events. It is useful in lab automation for turning internal conditions such as network reachability, CPU temperature, system load, time windows, or disk usage into triggers for controlling real instruments or experimental workflows.",
  "tag_hints": [
    "software pseudo-device",
    "polling events",
    "OS service monitoring",
    "network reachability ping",
    "CPU temperature monitoring",
    "load average monitoring",
    "disk usage monitoring",
    "time-based activation"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭该轮询式内部组件并停止后台监测。",
      "description_en": "Close the polled internal component and stop background monitoring."
    },
    {
      "action_name": "auto-event_delay",
      "description": "获取或设置用于事件检测的轮询时间间隔。",
      "description_en": "Get or set the polling interval used for event detection."
    },
    {
      "action_name": "auto-wait_for_active",
      "description": "等待组件进入激活状态，可设置超时。",
      "description_en": "Wait for the component to become active, with an optional timeout."
    },
    {
      "action_name": "auto-wait_for_inactive",
      "description": "等待组件进入未激活状态，可设置超时。",
      "description_en": "Wait for the component to become inactive, with an optional timeout."
    },
    {
      "action_name": "auto-closed",
      "description": "获取组件是否已关闭。",
      "description_en": "Get whether the component is closed."
    },
    {
      "action_name": "auto-host",
      "description": "获取用于连通性检测的主机名或 IP 地址。",
      "description_en": "Get the hostname or IP address used for reachability monitoring."
    },
    {
      "action_name": "auto-value",
      "description": "获取当前规范化数值输出。",
      "description_en": "Get the current normalized value output."
    },
    {
      "action_name": "auto-temperature",
      "description": "获取当前 CPU 温度。",
      "description_en": "Get the current CPU temperature."
    },
    {
      "action_name": "auto-is_active",
      "description": "获取当前是否处于激活状态。",
      "description_en": "Get whether the component is currently active."
    },
    {
      "action_name": "auto-load_average",
      "description": "获取当前 CPU 负载平均值。",
      "description_en": "Get the current CPU load average."
    },
    {
      "action_name": "auto-start_time",
      "description": "获取激活时间窗口的开始时间。",
      "description_en": "Get the start time of the active time window."
    },
    {
      "action_name": "auto-end_time",
      "description": "获取激活时间窗口的结束时间。",
      "description_en": "Get the end time of the active time window."
    },
    {
      "action_name": "auto-utc",
      "description": "获取或定义是否使用 UTC 时间进行比较。",
      "description_en": "Get or define whether UTC time is used for comparison."
    },
    {
      "action_name": "auto-usage",
      "description": "获取当前磁盘使用率。",
      "description_en": "Get the current disk usage percentage."
    }
  ]
}

